const THEMES=["light","gold","dark"],THEME_KEY="ea_theme",THEME_META={dark:{short:"D",label:"Dark",next:"light"},light:{short:"L",label:"Light",next:"gold"},gold:{short:"G",label:"Gold",next:"dark"}};function getTheme(){try{const e=localStorage.getItem(THEME_KEY);return THEMES.includes(e)?e:"light"}catch(e){return"light"}}function applyTheme(e){const t=THEMES.includes(e)?e:"light";document.documentElement.setAttribute("data-theme",t);try{localStorage.setItem(THEME_KEY,t)}catch(e){}const n=document.getElementById("theme-toggle-btn");if(!n)return;const l=THEME_META[t];n.title=`Switch to ${THEME_META[l.next].label} mode`,n.querySelector(".theme-icon").textContent=l.short,n.querySelector(".theme-label").textContent=l.label}function toggleTheme(){const e=getTheme();applyTheme(THEME_META[e]?.next||"light")}function injectToggleButton(){if(document.getElementById("theme-toggle-btn"))return;const e=document.createElement("button");e.id="theme-toggle-btn",e.setAttribute("aria-label","Toggle theme"),e.innerHTML='<span class="theme-icon" aria-hidden="true"></span><span class="theme-label"></span>',e.addEventListener("click",toggleTheme),document.body.appendChild(e)}document.addEventListener("DOMContentLoaded",()=>{injectToggleButton(),applyTheme(getTheme())}),applyTheme(getTheme());